# 1. 기존 스크립트 백업
cp /opt/betman/sync.sh /opt/betman/sync-v1.sh.bak 2>/dev/null || true

# 2. 새 스크립트 배포
echo "" | base64 -d > /opt/betman/sync.sh
chmod +x /opt/betman/sync.sh

# 3. 검증
echo "=== 배포 완료 ==="
head -3 /opt/betman/sync.sh
echo "..."
wc -l /opt/betman/sync.sh
echo ""
echo "=== crontab 확인 ==="
crontab -l 2>/dev/null | grep betman
echo ""
echo "=== 수동 테스트 실행 ==="
echo "bash /opt/betman/sync.sh; echo Exit: $?"
